(7620737, 1234027, 59740, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2019-03-19 22:13:07.000000', NULL, 1),
(7620740, 1233573, 59740, '<td valign="top">I really like your image especially the horses and riders. Since this challenge allows extended editing I would have cleaned up the background, especially the pole in the middle. Also, it seems a little tilted to the right. Overall its a nice shot.</td>', 'I really like your image especially the horses and riders. Since this challenge allows extended editing I would have cleaned up the background, especially the pole in the middle. Also, it seems a little tilted to the right. Overall its a nice shot.', '2019-03-19 22:16:01.000000', NULL, 1),
(7620742, 1232860, 59740, '<td valign="top">Great image of the dog. Since it''s allowed, I would have removed the background objects that don''t add to the story.</td>', 'Great image of the dog. Since it''s allowed, I would have removed the background objects that don''t add to the story.', '2019-03-19 22:17:22.000000', NULL, 1),
